import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
class PrivateTest {
@Test void contravarianceCovarianceNullAndIdentity(){Object[] seen={null};java.util.function.Predicate<Object> c=x->{seen[0]=x;return x==null;};java.util.function.Function<Object,Integer> yes=x->null;java.util.function.Function<CharSequence,Double> no=x->(double)x.length();java.util.function.Function<String,Number> f=TaskBinding.run(c,yes,no);assertNull(f.apply(null));String v=new String("abc");assertEquals(3.0,f.apply(v));assertSame(v,seen[0]);}
@Test void exactExceptionAndStopping(){var e=new IllegalStateException("same");int[] calls={0};var c=TaskBinding.<Object,Object>run(x->{throw e;},x->{calls[0]++;return x;},x->{calls[0]++;return x;});assertSame(e,assertThrows(IllegalStateException.class,()->c.apply(new Object())));assertEquals(0,calls[0]);var b=TaskBinding.<Object,Object>run(x->false,x->{calls[0]++;return x;},x->{throw e;});assertSame(e,assertThrows(IllegalStateException.class,()->b.apply(null)));assertEquals(0,calls[0]);}
@Test void sameArgumentAndOrderOnBothBranches(){Object value=new Object();var trace=new java.util.ArrayList<String>();boolean[] branch={true};var f=TaskBinding.<Object,Object>run(x->{assertSame(value,x);trace.add("condition");return branch[0];},x->{assertSame(value,x);trace.add("true");return x;},x->{assertSame(value,x);trace.add("false");return null;});assertSame(value,f.apply(value));branch[0]=false;assertNull(f.apply(value));assertEquals(java.util.List.of("condition","true","condition","false"),trace);}
@Test void trueBranchPreservesException(){var e=new IllegalArgumentException("identity");var f=TaskBinding.<Object,Object>run(x->true,x->{throw e;},x->{fail("unselected");return x;});assertSame(e,assertThrows(IllegalArgumentException.class,()->f.apply(null)));}
}
